model.en:
Emit an inline source map, add shortCircuit, and register via --import:

// loader.js
import { readFile } from "node:fs/promises";
import { transform } from "some-fast-transpiler";

export async function load(url, context, nextLoad) {
  if (!url.endsWith(".ts")) return nextLoad(url, context);
  const raw = await readFile(new URL(url), "utf8");
  const { code } = await transform(raw, { sourcemap: "inline" }); // ✅ map travels with the source
  return { format: "module", source: code, shortCircuit: true };  // ✅ deliberate handle
}

// register.js (new)
import { register } from "node:module";
register("./loader.js", import.meta.url);

// run: node --import ./register.js app.ts   (NOT --loader)

Why it's right: sourcemap: 'inline' embeds a base64 map in the returned source, so Node's source-map support (on by default; --enable-source-maps forces it) remaps V8's captured positions back to the original .ts — traces point at real lines. shortCircuit: true tells Node you handled this without calling nextLoad, so it doesn't throw. And register(specifier, parentURL) is the modern replacement for the removed/deprecated --loader: run it before the app via --import so hooks are installed before app.ts and its imports are resolved.

